import re, pathlib
base=pathlib.Path('c:/git/compose')
files=[('go','compose/go/main.go',r'^// #region (.+)$',r'^// #endregion (.+)$'),('ts','compose/js/index.ts',r'^// #region (.+)$',r'^// #endregion (.+)$'),('py','compose/py/main.py',r'^# #region (.+)$',r'^# #endregion (.+)$'),('cs','compose/net/Compose/Compose.cs',r'^#region (.+)$',r'^#endregion (.+)$')]
for lang,rel,s,e in files:
    st=[]; ok=True
    for i,l in enumerate((base/rel).read_text(encoding='utf-8').splitlines(),1):
        m=re.match(s,l.rstrip())
        if m: st.append((m.group(1),i))
        m=re.match(e,l.rstrip())
        if m:
            if not st:
                ok=False; print(lang,'extra end',i,m.group(1)); continue
            n,ln=st.pop()
            if n!=m.group(1):
                ok=False; print(lang,'mismatch',ln,n,'!=',i,m.group(1))
    if st:
        ok=False; print(lang,'unclosed',[(n,ln) for n,ln in st[:5]],'count',len(st))
    if ok: print(lang,'regions balanced')
